begin;
update public.learning_materials set steps='["Hubungkan ponsel ke internet dan buka Benang-Mawar. Kenali menu Belanja Tenun, Ruang Belajar, dan Tentang Kami.","Pilih akun sesuai peran: pembeli untuk belanja, penjual untuk etalase, dan admin untuk pengelolaan koperasi.","Latihan bersama pendamping: buka satu panduan, baca langkahnya, lalu coba sendiri. Ulangi bila perlu."]'::jsonb where id=1;
update public.learning_materials set title='Penjual: siapkan dan kelola kain',steps='["Siapkan foto kain asli, nama produk dan pembuat, motif, ukuran, bahan, harga, stok, serta cerita kain.","Masuk sebagai Penjual lalu buka Etalase Produk. Tambahkan atau edit kain dan simpan. Foto tersimpan di Cloudinary dan data produk di Supabase.","Produk diperiksa admin sebelum tayang. Periksa catatan admin jika ada perbaikan. Gunakan minus, plus, Stok habis, atau Hapus produk untuk mengatur persediaan.","Buka Pesanan masuk untuk menerima pesanan yang sudah dibayar. Proses barang, tandai dikirim dan tiba sesuai kondisi nyata. Penjual mengelola barang serta pesanan miliknya."]'::jsonb where id=3;
update public.learning_materials set steps=jsonb_set(steps,'{0}','"Masuk sebagai admin koperasi lalu buka Kelola Koperasi. Periksa data seluruh produk, termasuk kain yang diajukan penjual."'::jsonb) where id=4;
commit;
